-- Run this third: stages platform/follower rows and imports them.
DROP TABLE IF EXISTS _creator_platform_import;
CREATE TABLE _creator_platform_import (
  creator_id uuid NOT NULL,
  platform "PlatformType" NOT NULL,
  handle text NOT NULL,
  followers integer NOT NULL,
  verified boolean NOT NULL DEFAULT false,
  profile_url text
);


DELETE FROM "CreatorPlatform"
WHERE "creatorId" IN (SELECT creator_id::text FROM _creator_platform_import);

  "id",
  "creatorId",
  "platform",
  "handle",
  "followers",
  "verified",
  "profileUrl",
  "lastUpdated"
)
SELECT
  gen_random_uuid(),
  creator_id::text,
  platform,
  handle,
  followers,
  verified,
  profile_url,
  CURRENT_TIMESTAMP
FROM _creator_platform_import;
